package com.ethk3.novaonepro.r952;
import android.content.Context;import android.graphics.Canvas;import android.graphics.Color;import android.graphics.Paint;import android.view.*;import android.app.AlertDialog;import java.util.*;
import static com.ethk3.novaonepro.ResearchVisualDataR82.*;
/** Native local drawing from immutable bounded DTOs; no DB/network/model work in draw or touch. */
// Built only in code around one immutable Panel; never inflated from XML.
@android.annotation.SuppressLint("ViewConstructor")
public final class ResearchChartViewR82 extends View {
 private final Panel panel;private final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);private final float density;private final Map<String,float[]> nodes=new LinkedHashMap<>();private int selected;
 private final int blue=Color.rgb(63,181,255),green=Color.rgb(84,218,172),muted=Color.rgb(164,182,204);
 public ResearchChartViewR82(Context context,Panel panel){super(context);this.panel=panel;density=getResources().getDisplayMetrics().density;setContentDescription(panel.title+"。"+panel.note+"。点击图形选择真实样本或打开样本列表。");setFocusable(true);setClickable(true);}
 private int dp(float n){return Math.round(n*density);}private boolean finite(double v){return ChartGeometryR82.finite(v);}private String brief(String s,int n){return s.length()<=n?s:s.substring(0,n)+"…";}
 @Override protected void onMeasure(int w,int h){setMeasuredDimension(MeasureSpec.getSize(w),resolveSize(dp(panel.kind.equals("GRAPH")?340:270),h));}
 private void text(Canvas c,String s,float x,float y,int color,float size){pen.setColor(color);pen.setTextSize(dp(size));pen.setStyle(Paint.Style.FILL);c.drawText(s,x,y,pen);}
 // The bounded range buffer is sized by the immutable panel and redraws are on demand, not animated.
 @android.annotation.SuppressLint("DrawAllocation")
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(19,34,53));if(panel.points.isEmpty()){text(c,"暂无真实可绘样本",dp(16),dp(52),muted,15);text(c,brief(panel.status,40),dp(16),dp(84),muted,12);return;}if(panel.kind.equals("GRAPH")){graph(c);return;}if(panel.kind.equals("HEATMAP")){heat(c);return;}
  float left=dp(56),right=getWidth()-dp(18),top=dp(24),bottom=getHeight()-dp(50);double[] vals=new double[panel.points.size()*4];int k=0;for(Point p:panel.points){vals[k++]=p.value;vals[k++]=p.lower;vals[k++]=p.upper;vals[k++]=p.open;}double[] range=ChartGeometryR82.range(vals);boolean reliability=panel.kind.equals("RELIABILITY");if(reliability)range=new double[]{0,1};double lo=range[0],hi=range[1];
  for(int i=0;i<=4;i++){double v=lo+(hi-lo)*i/4;float y=ChartGeometryR82.y(v,lo,hi,top,bottom);pen.setColor(Color.rgb(43,62,84));pen.setStrokeWidth(dp(1));c.drawLine(left,y,right,y,pen);text(c,String.format(Locale.ROOT,"%.3g",v),dp(3),y+dp(4),muted,11);}if(reliability){pen.setColor(muted);c.drawLine(left,bottom,right,top,pen);}
  boolean bars=panel.kind.equals("BAR")||panel.kind.equals("EVENTS");float px=0,py=0;boolean previous=false;int n=panel.points.size();for(int i=0;i<n;i++){Point p=panel.points.get(i);float x=ChartGeometryR82.x(i,n,left,right);if(reliability){double expected=predicted(p);if(!finite(expected)){previous=false;continue;}x=left+(float)expected*(right-left);}if(!finite(p.value)){previous=false;continue;}float y=ChartGeometryR82.y(p.value,lo,hi,top,bottom);pen.setStrokeWidth(dp(2));pen.setColor(blue);
   if(panel.kind.equals("CANDLE")){if(!finite(p.open)||!finite(p.lower)||!finite(p.upper)){previous=false;continue;}pen.setColor(p.value>=p.open?green:Color.rgb(255,133,133));float open=ChartGeometryR82.y(p.open,lo,hi,top,bottom),width=Math.max(dp(2),Math.min(dp(9),(right-left)/n*.65f));c.drawLine(x,ChartGeometryR82.y(p.lower,lo,hi,top,bottom),x,ChartGeometryR82.y(p.upper,lo,hi,top,bottom),pen);c.drawRect(x-width/2,Math.min(y,open)-dp(.5f),x+width/2,Math.max(y,open)+dp(.5f),pen);}
   else {if(finite(p.lower)&&finite(p.upper)){pen.setColor(green);float a=ChartGeometryR82.y(p.lower,lo,hi,top,bottom),b=ChartGeometryR82.y(p.upper,lo,hi,top,bottom);c.drawLine(x,a,x,b,pen);c.drawLine(x-dp(3),a,x+dp(3),a,pen);c.drawLine(x-dp(3),b,x+dp(3),b,pen);pen.setColor(blue);}if(bars){float z=ChartGeometryR82.y(Math.max(lo,Math.min(hi,0)),lo,hi,top,bottom);c.drawLine(x,z,x,y,pen);}else if(previous)c.drawLine(px,py,x,y,pen);c.drawCircle(x,y,dp(2.7f),pen);}previous=true;px=x;py=y;}
  text(c,brief(panel.points.get(0).label,20),left,bottom+dp(20),muted,10);String tail=brief(panel.points.get(n-1).label,20);pen.setTextSize(dp(10));text(c,tail,Math.max(left,right-pen.measureText(tail)),bottom+dp(35),muted,10);
 }
 private double predicted(Point p){if(finite(p.expected)&&p.expected>=0&&p.expected<=1)return p.expected;try{double x=Double.valueOf(p.label.substring(p.label.indexOf(':')+1));return x>=0&&x<=1?x:Double.NaN;}catch(RuntimeException e){return Double.NaN;}}
 private void heat(Canvas c){float size=Math.min((getWidth()-dp(32))/10f,dp(26));double[] values=new double[panel.points.size()];for(int i=0;i<values.length;i++)values[i]=panel.points.get(i).value;double[] r=ChartGeometryR82.range(values);for(int i=0;i<values.length;i++){double v=values[i];float x=dp(16)+(i%10)*size,y=dp(20)+(i/10)*size,level=finite(v)?(float)((v-r[0])/(r[1]-r[0])):0;pen.setColor(finite(v)?Color.rgb((int)(32+30*level),(int)(70+130*level),(int)(105+125*level)):Color.rgb(47,52,62));c.drawRect(x,y,x+size-dp(1),y+size-dp(1),pen);}text(c,"灰格=未知；色阶按当前面板范围",dp(16),getHeight()-dp(14),muted,11);}
 private void graph(Canvas c){List<String> names=new ArrayList<>();for(Point p:panel.points)names.add(p.label);nodes.clear();nodes.putAll(ChartGeometryR82.graph(names,getWidth(),getHeight()));pen.setStrokeWidth(dp(1));for(Edge e:panel.edges){float[] f=nodes.get(e.from),t=nodes.get(e.to);if(f==null||t==null)continue;pen.setColor(Color.rgb(73,113,155));c.drawLine(f[0],f[1],t[0],t[1],pen);double a=Math.atan2(t[1]-f[1],t[0]-f[0]);float x=t[0]-(float)Math.cos(a)*dp(7),y=t[1]-(float)Math.sin(a)*dp(7);for(double da:new double[]{-.45,.45})c.drawLine(x,y,x-(float)Math.cos(a+da)*dp(7),y-(float)Math.sin(a+da)*dp(7),pen);}for(Map.Entry<String,float[]> e:nodes.entrySet()){float[] p=e.getValue();pen.setColor(green);c.drawCircle(p[0],p[1],dp(5),pen);text(c,brief(e.getKey(),10),Math.max(dp(4),Math.min(getWidth()-dp(92),p[0]+dp(7))),p[1],muted,10);}}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;if(panel.points.isEmpty())return performClick();if(panel.kind.equals("GRAPH")){double best=Double.POSITIVE_INFINITY;for(int i=0;i<panel.points.size();i++){float[] xy=nodes.get(panel.points.get(i).label);if(xy==null)continue;double d=Math.pow(e.getX()-xy[0],2)+Math.pow(e.getY()-xy[1],2);if(d<best){best=d;selected=i;}}}else if(panel.kind.equals("HEATMAP")){float size=Math.min((getWidth()-dp(32))/10f,dp(26));int col=Math.max(0,Math.min(9,(int)((e.getX()-dp(16))/size))),row=Math.max(0,(int)((e.getY()-dp(20))/size));selected=Math.min(panel.points.size()-1,row*10+col);}else if(panel.kind.equals("RELIABILITY")){double best=Double.POSITIVE_INFINITY;for(int i=0;i<panel.points.size();i++){double x=predicted(panel.points.get(i)),d=Math.abs(e.getX()-(dp(56)+x*(getWidth()-dp(74))));if(finite(x)&&d<best){best=d;selected=i;}}}else selected=ChartGeometryR82.nearest(e.getX(),panel.points.size(),dp(56),getWidth()-dp(18));return performClick();}
 @Override public boolean performClick(){super.performClick();details();return true;}
 private void details(){if(panel.points.isEmpty())return;selected=Math.max(0,Math.min(selected,panel.points.size()-1));Point p=panel.points.get(selected);StringBuilder b=new StringBuilder("来源：").append(panel.source).append("\n窗口：").append(panel.window).append("\n").append(panel.note).append("\n\n").append(p.label).append("\n值：").append(finite(p.value)?p.value:"未知").append("；N：").append(p.n<0?"未记录":p.n).append("\n区间：").append(finite(p.lower)?p.lower:"未知").append(" — ").append(finite(p.upper)?p.upper:"未知").append("\n").append(p.details);for(Edge e:panel.edges)if(e.from.equals(p.label)||e.to.equals(p.label))b.append("\n").append(e.from).append(" → ").append(e.to).append("\n").append(e.label);android.widget.TextView t=new android.widget.TextView(getContext());t.setPadding(dp(16),dp(12),dp(16),dp(12));t.setText(b);t.setTextIsSelectable(true);android.widget.ScrollView s=new android.widget.ScrollView(getContext());s.addView(t);new AlertDialog.Builder(getContext()).setTitle(panel.title).setView(s).setPositiveButton("关闭",null).setNeutralButton("其他样本",(d,w)->{String[] labels=new String[panel.points.size()];for(int i=0;i<labels.length;i++)labels[i]=panel.points.get(i).label;new AlertDialog.Builder(getContext()).setItems(labels,(dialog,index)->{selected=index;details();}).show();}).show();}
}
